<h2>Estimate exercise sweat rate</h2><p class="lead">Use a before-and-after weigh-in plus measured fluid intake to estimate sweat loss during a training session.</p>
<div class="form-grid"><div class="field"><label for="pre">Pre-exercise body mass (kg)</label><input id="pre" type="number" min="0" step="any" value="70"></div><div class="field"><label for="post">Post-exercise body mass (kg)</label><input id="post" type="number" min="0" step="any" value="69.4"></div><div class="field"><label for="drink">Fluid consumed (L)</label><input id="drink" type="number" min="0" step="any" value="0.5"></div><div class="field"><label for="urine">Urine during session (L)</label><input id="urine" type="number" min="0" step="any" value="0"></div><div class="field"><label for="mins">Exercise duration (minutes)</label><input id="mins" type="number" min="1" step="any" value="60"></div></div>
<div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Estimate sweat rate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div>
<div class="result-box"><div class="result-grid"><div class="metric"><span>Estimated sweat loss</span><strong id="loss">—</strong></div><div class="metric"><span>Sweat rate</span><strong id="rate">—</strong></div><div class="metric"><span>Body-mass change</span><strong id="change">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div>
<script>
(()=>{const $=id=>document.getElementById(id),n=id=>parseFloat($(id).value);function go(){const pre=n('pre'),post=n('post'),drink=n('drink'),ur=n('urine'),mins=n('mins');if(![pre,post,drink,ur,mins].every(Number.isFinite)||pre<=0||post<=0||drink<0||ur<0||mins<=0){$('note').textContent='Enter positive body masses and duration, plus non-negative fluid and urine volumes.';$('note').className='helper danger';return;}const massLoss=pre-post,sweat=massLoss+drink-ur,rate=sweat/(mins/60),pct=(post-pre)/pre*100;$('loss').textContent=sweat.toFixed(2)+' L';$('rate').textContent=rate.toFixed(2)+' L/h';$('change').textContent=pct.toFixed(2)+'%';let msg='Use repeated measurements in similar conditions to understand your personal range. Sweat rate changes with temperature, clothing, intensity, acclimatization and body size.';if(sweat<0)msg='The calculated sweat loss is negative, which usually indicates inconsistent measurements, unrecorded fluid, scale error or a timing issue. '+msg;$('note').textContent=msg;$('note').className='helper'+(sweat<0?' danger':'');}
['pre','post','drink','urine','mins'].forEach(id=>$(id).addEventListener('input',go));$('calc').onclick=go;$('reset').onclick=()=>{$('pre').value=70;$('post').value=69.4;$('drink').value=.5;$('urine').value=0;$('mins').value=60;go();};go();})();
</script>
